<script lang="ts">
	import { Activity, Camera, ChevronRight, Home, Play, RefreshCw, Thermometer, X } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import BmsLiveStringPanel from './BmsLiveStringPanel.svelte';
	import { getBmsDashboardSnapshot, getCalibrationEvent, hasBmsSession, listCalibrationEvents, type BmsDashboardItem, type CalibrationEventDetail } from '$lib/services/bms-api';
	import { BMS_ASSET_PROFILE_EVENT, emptyBmsSiteProfile, loadBmsAssetProfile, type BmsSiteProfile } from '$lib/services/bms-asset-profile';

	let { onOpenCalibration = (_stringIndex:number) => undefined }: { onOpenCalibration?: (stringIndex:number) => void } = $props();
	let site=$state<BmsSiteProfile>(emptyBmsSiteProfile());
	let cameraEnabled=$state(false),items=$state<BmsDashboardItem[]>([]),loading=$state(false),error=$state('');
	let activeCalibration=$state<CalibrationEventDetail|null>(null);
	let calibrateOpen=$state(false),confirmCalibration=$state(false),calibrationStringIndex=$state(0);
	let alarmStrings=$derived(items.filter(item=>statusFor(item)==='alarm').length);
	let offlineStrings=$derived(items.filter(item=>statusFor(item)==='offline').length);
	let selectedCalibrationString=$derived(items.find(item=>item.config.stringIndex===calibrationStringIndex)?.config??null);
	let activeStage=$derived(activeCalibration?.stages.find(stage=>stage.calibrationStageId===activeCalibration?.currentStageId)??null);

	onMount(()=>{site=loadBmsAssetProfile().site;const updateSite=()=>site=loadBmsAssetProfile().site;window.addEventListener(BMS_ASSET_PROFILE_EVENT,updateSite);void load();const timer=setInterval(()=>void load(false),15000);return()=>{clearInterval(timer);window.removeEventListener(BMS_ASSET_PROFILE_EVENT,updateSite)}});
	async function load(showActivity=true){
		if(!hasBmsSession()){items=[];error='Connecting to the BMS platform…';return}
		if(showActivity)loading=true;
		try{const[data,events]=await Promise.all([getBmsDashboardSnapshot(),listCalibrationEvents().catch(()=>[])]);items=data;const running=events.find(event=>['ACTIVE','BLOCKED','REVALIDATION_REQUIRED'].includes(event.status));activeCalibration=running?await getCalibrationEvent(running.calibrationEventId).catch(()=>null):null;error=''}
		catch(cause){error=cause instanceof Error?cause.message:'Unable to load the BMS dashboard.'}
		finally{loading=false}
	}
	function display(value:string){return value.trim()||'Not set'}
	function openCalibrate(){calibrationStringIndex=items[0]?.config.stringIndex??0;confirmCalibration=false;calibrateOpen=true}
	function continueCalibration(){if(calibrationStringIndex)confirmCalibration=true}
	function openCalibrationWorkspace(){if(!calibrationStringIndex)return;calibrateOpen=false;confirmCalibration=false;onOpenCalibration(calibrationStringIndex)}
	function viewActiveCalibration(){if(activeCalibration){onOpenCalibration(Number(activeCalibration.stringId.replace(/^str/,''))||items[0]?.config.stringIndex||0)}}
	function alarms(item:BmsDashboardItem){const summary=item.telemetry.summary,config=item.config,reasons:string[]=[];if(summary.maxResistance!==null&&config.highResistanceThreshold>0&&summary.maxResistance>=config.highResistanceThreshold)reasons.push('R');if(summary.maxTemperature!==null&&config.highTemperatureThreshold>0&&summary.maxTemperature>=config.highTemperatureThreshold)reasons.push('T');if(summary.minVoltage!==null&&config.lowVoltageThreshold>0&&summary.minVoltage<=config.lowVoltageThreshold)reasons.push('V');if(summary.maxVoltage!==null&&config.highVoltageThreshold>0&&summary.maxVoltage>=config.highVoltageThreshold)reasons.push('V');return[...new Set(reasons)]}
	function disconnected(item:BmsDashboardItem){const summary=item.telemetry.summary;return!item.telemetry.active||[summary.avgVoltage,summary.avgResistance,summary.stringVoltage,summary.stringCurrent,summary.avgTemperature].every(value=>value===null)}
	function statusFor(item:BmsDashboardItem){return alarms(item).length?'alarm':disconnected(item)?'offline':'normal'}
</script>

<section class="page">
	<div class="site-card">
		<span class="site-icon"><Home size={20}/></span>
		<div class="site-facts"><div><span>Owner</span><strong>{display(site.owner)}</strong></div><div><span>Operational team</span><strong>{display(site.operationalTeam)}</strong></div><div><span>Substation</span><strong>{display(site.substation)}</strong></div></div>
		<div class="fleet-summary"><span><strong>{items.length}</strong> strings</span><span class:has-alarm={alarmStrings>0}><strong>{alarmStrings}</strong> alarm</span><span class:has-offline={offlineStrings>0}><strong>{offlineStrings}</strong> offline</span></div>
		<button class="calibrate" type="button" disabled={!items.length} onclick={openCalibrate}><Activity size={17}/>Calibrate</button>
		<button class:loading class="refresh" aria-label="Refresh dashboard" disabled={loading} onclick={()=>load()}><RefreshCw size={18}/></button>
	</div>
	{#if activeCalibration}<section class="active-calibration"><span class="pulse"></span><div><small>Calibration in progress · {activeCalibration.stringId}</small><strong>{activeCalibration.eventType.replaceAll('_',' ')} · {activeStage?activeStage.type.replaceAll('_',' '):'Preparing event'}</strong></div><span class="event-state">{activeCalibration.status.replaceAll('_',' ')}</span><button type="button" onclick={viewActiveCalibration}>View details<ChevronRight size={16}/></button></section>{/if}

	{#if error}<div class="request-error">{error}</div>{/if}

	{#if loading&&!items.length}
		<div class="loading-card"><i></i><strong>Loading live string data…</strong></div>
	{:else if items.length}
		<div class="string-grid">{#each items as item (item.config.id)}<BmsLiveStringPanel {item}/>{/each}</div>
	{:else}
		<div class="empty-card"><strong>No battery strings configured</strong><span>Add a string in Battery Strings to begin monitoring.</span></div>
	{/if}

	<details class="thermal-card"><summary><span><Thermometer size={17}/>Thermal camera</span><small>Optional room monitoring</small></summary><div class="thermal-content"><Camera size={19}/><span>{cameraEnabled?'Thermal monitoring is enabled.':'No thermal data available.'}</span><button class:active={cameraEnabled} onclick={()=>cameraEnabled=!cameraEnabled}>{cameraEnabled?'Turn off':'Turn on'}</button></div></details>
	{#if calibrateOpen}<div class="modal-backdrop" role="presentation"><section class="calibrate-dialog" role="dialog" aria-modal="true" aria-labelledby="calibrate-title"><header><div><h2 id="calibrate-title">{confirmCalibration?'Confirm calibration':'Select battery string'}</h2><p>{confirmCalibration?'Review the selected string before opening the event workflow.':'Choose the string you want to calibrate.'}</p></div><button type="button" aria-label="Close calibration dialog" onclick={()=>calibrateOpen=false}><X size={19}/></button></header>{#if confirmCalibration}<div class="confirmation"><span>{@render BatterySummary(selectedCalibrationString)}</span><p>Telemetry for this string will continue updating on Health Monitor while the Calibration Event runs in the background.</p></div>{:else}<div class="string-options">{#each items as item}<label class:selected={calibrationStringIndex===item.config.stringIndex}><input type="radio" name="calibration-string" value={item.config.stringIndex} bind:group={calibrationStringIndex}/><span><strong>{item.config.stringName}</strong><small>{item.config.cellQty} cells · {item.config.cellBrand} {item.config.cellModel}</small></span></label>{/each}</div>{/if}<footer><button class="secondary" type="button" onclick={()=>confirmCalibration?confirmCalibration=false:calibrateOpen=false}>{confirmCalibration?'Back':'Cancel'}</button><button class="primary" type="button" disabled={!calibrationStringIndex} onclick={confirmCalibration?openCalibrationWorkspace:continueCalibration}>{#if confirmCalibration}<Play size={16}/>{/if}{confirmCalibration?'Open Calibration Event':'Continue'}</button></footer></section></div>{/if}
</section>

{#snippet BatterySummary(item: BmsDashboardItem['config']|null)}
	{#if item}<strong>{item.stringName}</strong><small>str{item.stringIndex} · {item.cellQty} cells · {item.ratedCapacity} Ah</small>{:else}<strong>No string selected</strong>{/if}
{/snippet}

<style>
	.page{animation:enter .18s ease-out}.site-card{display:flex;align-items:center;gap:14px;min-height:76px;padding:13px 15px;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.site-icon{display:grid;flex:0 0 38px;width:38px;height:38px;place-items:center;border-radius:9px;color:#2653ba;background:#eaf0ff}.site-facts{display:grid;grid-template-columns:repeat(3,minmax(120px,1fr));min-width:0;max-width:760px;flex:1}.site-facts>div{min-width:0;padding:0 15px;border-right:1px solid #e7ecf3}.site-facts>div:first-child{padding-left:0}.site-facts>div:last-child{border-right:0}.site-facts span,.site-facts strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.site-facts span{color:#78859a;font-size:11px}.site-facts strong{margin-top:5px;color:#2f425e;font-size:14px;font-weight:600}.fleet-summary{display:flex;gap:7px;margin-left:auto}.fleet-summary span{display:inline-flex;align-items:baseline;gap:4px;padding:6px 9px;border-radius:13px;color:#647187;background:#f3f5f8;font-size:11px}.fleet-summary strong{color:#35465f;font-size:13px;font-weight:500}.fleet-summary .has-alarm{color:#a74138;background:#fff0ef}.fleet-summary .has-alarm strong{color:#b7352c}.fleet-summary .has-offline{color:#6e7785;background:#edf0f4}.calibrate{display:inline-flex;align-items:center;gap:7px;height:38px;padding:0 12px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.calibrate:disabled{opacity:.5;cursor:not-allowed}.refresh{display:grid;width:36px;height:36px;place-items:center;border:1px solid #d9e1ec;border-radius:8px;color:#496389;background:#fff;cursor:pointer}.refresh.loading :global(svg){animation:spin .8s linear infinite}.request-error{margin-top:10px;padding:9px 11px;border:1px solid #efddae;border-radius:8px;color:#765b28;background:#fff9e9;font-size:12px}.active-calibration{display:flex;align-items:center;gap:10px;margin-top:10px;padding:10px 12px;border:1px solid #d5e3f7;border-radius:9px;color:#385274;background:#f4f8ff}.active-calibration .pulse{width:9px;height:9px;border-radius:50%;background:#2f70cf;box-shadow:0 0 0 5px rgba(47,112,207,.12)}.active-calibration div{display:grid;gap:3px}.active-calibration small{color:#647997;font-size:11px}.active-calibration strong{color:#2e4565;font-size:13px;font-weight:600}.event-state{margin-left:auto;padding:4px 8px;border-radius:12px;color:#285aa9;background:#e4edfc;font-size:10px;font-weight:700}.active-calibration button{display:inline-flex;align-items:center;gap:4px;border:0;color:#1749ad;background:transparent;font:inherit;font-size:12px;font-weight:600;cursor:pointer}
	.string-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start;margin-top:14px}.loading-card,.empty-card{display:grid;min-height:330px;margin-top:14px;place-content:center;justify-items:center;border:1px solid #e1e7f0;border-radius:12px;color:#79869a;background:#fff;text-align:center}.loading-card i{width:25px;height:25px;margin-bottom:10px;border:2px solid #dce5f2;border-top-color:#2c5ab4;border-radius:50%;animation:spin .8s linear infinite}.loading-card strong,.empty-card strong{color:#40516c;font-size:14px;font-weight:500}.empty-card span{margin-top:6px;font-size:12px}.thermal-card{margin-top:14px;border:1px solid #e1e7f0;border-radius:10px;background:#fff}.thermal-card summary{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;color:#4b5d76;cursor:pointer;list-style:none}.thermal-card summary::-webkit-details-marker{display:none}.thermal-card summary span{display:flex;align-items:center;gap:7px;font-size:13px}.thermal-card summary small{color:#8a95a6}.thermal-content{display:flex;align-items:center;gap:8px;padding:12px 13px;border-top:1px solid #edf1f5;color:#7b8799;font-size:12px}.thermal-content button{margin-left:auto;padding:5px 9px;border:0;border-radius:6px;color:#4d6385;background:#edf2f9;cursor:pointer}.thermal-content button.active{color:#28734b;background:#ebf7ef}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(4px)}}
	.site-card{min-height:84px;padding:15px 17px}.site-icon{width:42px;height:42px}.fleet-summary{gap:8px}.fleet-summary span{padding:7px 11px;font-size:13px}.fleet-summary strong{font-size:15px;font-weight:600}.refresh{width:40px;height:40px}.request-error{font-size:14px}.loading-card strong,.empty-card strong{font-size:16px}.empty-card span{font-size:14px}.thermal-card summary{padding:14px 15px}.thermal-card summary span{gap:8px;font-size:16px;font-weight:500}.thermal-card summary small{color:#63738a;font-size:13px}.thermal-content{padding:14px 15px;color:#596b82;font-size:14px}.thermal-content button{padding:7px 11px;font-size:14px}.modal-backdrop{position:fixed;inset:0;z-index:400;display:grid;place-items:center;padding:18px;background:rgba(20,35,60,.32)}.calibrate-dialog{width:min(520px,100%);overflow:hidden;border:1px solid #dfe6ef;border-radius:13px;background:#fff;box-shadow:0 24px 70px rgba(22,40,72,.24)}.calibrate-dialog>header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:18px 20px;border-bottom:1px solid #e8edf4}.calibrate-dialog h2{margin:0;color:#263a57;font-size:19px}.calibrate-dialog header p{margin:5px 0 0;color:#718096;font-size:13px}.calibrate-dialog header button{display:grid;width:30px;height:30px;place-items:center;border:0;border-radius:7px;color:#617087;background:#f3f6fa;cursor:pointer}.string-options{display:grid;gap:8px;padding:18px 20px}.string-options label{display:flex;align-items:center;gap:11px;padding:12px;border:1px solid #e0e7f0;border-radius:9px;cursor:pointer}.string-options label.selected{border-color:#91afe1;background:#f4f8ff}.string-options input{width:16px;height:16px;accent-color:#1749ad}.string-options label span,.confirmation>span{display:grid;gap:4px}.string-options strong,.confirmation strong{color:#30445f;font-size:14px}.string-options small,.confirmation small{color:#748299;font-size:12px}.confirmation{padding:20px}.confirmation>span{padding:14px;border-radius:9px;background:#f4f7fb}.confirmation p{margin:14px 0 0;color:#617188;font-size:13px;line-height:1.5}.calibrate-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:12px 20px;border-top:1px solid #e8edf4}.calibrate-dialog footer button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border-radius:8px;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.calibrate-dialog footer .secondary{border:1px solid #d8e0eb;color:#40516f;background:#fff}.calibrate-dialog footer .primary{border:0;color:#fff;background:#1749ad}.calibrate-dialog footer button:disabled{opacity:.5;cursor:not-allowed}
	@media(max-width:1180px){.string-grid{grid-template-columns:1fr}.site-facts{max-width:none}}@media(max-width:900px){.site-card{align-items:flex-start;flex-wrap:wrap}.site-facts{order:2;flex-basis:calc(100% - 60px)}.fleet-summary{order:3;width:100%;margin-left:0}.calibrate{margin-left:auto}}@media(max-width:620px){.site-facts{grid-template-columns:1fr;gap:9px}.site-facts>div{padding:0;border:0}.active-calibration{align-items:flex-start;flex-wrap:wrap}.event-state{margin-left:0}.active-calibration button{margin-left:auto}}@media(max-width:520px){.fleet-summary{flex-wrap:wrap}.calibrate{order:4;width:100%;justify-content:center}}
</style>
